        parse_transcript_log([" # skipped", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 3, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_dedupe_transcripts_sorts_by_day_then_id():
    events = [
        {"id": "z", "day": 1, "flagged": True},
        {"id": "b", "day": 1, "flagged": False},
    ]
    assert [event["id"] for event in dedupe_transcripts(events)] == ["b", "z"]


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [0, 1, 1]
