    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_ties_empty_exclusion():
    groups = {
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "empty": [],
        "lower": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["a", "z", "lower"]


